529	+         type Select2<T, K extends keyof T> = Select<T, K>;\n\
530	+         type Drop<T, K extends keyof T> = Omit<T, K>;\n\
531	+         type Keys = 'id' | 'title';\n\
532	+         interface Names { k: 'id' | 'title' }\n\
533	+         interface Chosen { id?: string; title?: string }\n",
